    @EventHandler( payloadType=CreatePatientEvent.class )
    public void handle( CreatePatientEvent event) {
	    LOGGER.info("handling CreatePatientEvent - " + event );
	    Patient entity = new Patient();
            entity.setPatientId( event.getPatientId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setMrn( event.getMrn() );
            entity.setDateOfBirth( event.getDateOfBirth() );
            entity.setAddress( event.getAddress() );
            entity.setPrimaryLanguage( event.getPrimaryLanguage() );
            entity.setSexAtBirth( event.getSexAtBirth() );
            entity.setBloodType( event.getBloodType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPatient( entity );
    }

