    /**
     * Method to retrieve the Patient via an PatientPrimaryKey.
     * @param 	id Long
     * @return 	Patient
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Patient handle( FindPatientQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPatientId() );
    }
    
    /**
     * Method to retrieve a collection of all Patients
     *
     * @param	query	FindAllPatientQuery 
     * @return 	List<Patient> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Patient> handle( FindAllPatientQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPatient,
 * but only if the id matches
 *
 * @param		entity	Patient
 */
	protected void emitFindPatient( Patient entity ) {
		LOGGER.info("handling emitFindPatient" );
		
	    queryUpdateEmitter.emit(FindPatientQuery.class,
	                            query -> query.getFilter().getPatientId().equals(entity.getPatientId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPatient
	 * 
	 * @param		entity	Patient
	 */
	protected void emitFindAllPatient( Patient entity ) {
		LOGGER.info("handling emitFindAllPatient" );
		
	    queryUpdateEmitter.emit(FindAllPatientQuery.class,
	                            query -> true,
	                            entity);
	}

